import osmtogeojson from "osmtogeojson";
import Papa from "papaparse";
import fs from "fs";

// small midtown bbox for speed
const q = `[out:json][timeout:60];area["name"="Manhattan Island"]->.a;(way["building"](40.755,-73.99,40.765,-73.97)(area.a););out geom;`;
const res = await fetch("https://overpass-api.de/api/interpreter",{method:"POST",body:q});
const raw = await res.json();
const gj = osmtogeojson(raw);
const buildings = gj.features.filter(f=>f.properties?.building && (f.geometry.type==="Polygon"||f.geometry.type==="MultiPolygon"));
console.log("buildings fetched:", buildings.length, "sample id:", buildings[0]?.id);

const csv = fs.readFileSync("public/data/noise.csv","utf8");
const rows = Papa.parse(csv,{header:true,skipEmptyLines:true}).data;
const noise = rows.filter(r=>/noise/i.test(r["Complaint Type"]||"") && isFinite(parseFloat(r.Latitude)))
  .map(r=>({lon:+r.Longitude,lat:+r.Latitude}));
console.log("noise points:", noise.length);

const LAT=40.78, MLAT=111320, MLON=111320*Math.cos(LAT*Math.PI/180), R=500;
function ringCentroid(ring){let A=0,cx=0,cy=0;for(let i=0;i<ring.length-1;i++){const[x0,y0]=ring[i],[x1,y1]=ring[i+1];const c=x0*y1-x1*y0;A+=c;cx+=(x0+x1)*c;cy+=(y0+y1)*c;}if(Math.abs(A)<1e-12){let sx=0,sy=0;for(const[x,y]of ring){sx+=x;sy+=y;}return[sx/ring.length,sy/ring.length];}A*=.5;return[cx/(6*A),cy/(6*A)];}
function cent(f){const g=f.geometry;if(g.type==="Polygon")return ringCentroid(g.coordinates[0]);let b=null;for(const p of g.coordinates)if(!b||p[0].length>b.length)b=p[0];return ringCentroid(b);}
function dist(a,b,c,d){return Math.hypot((a-c)*MLON,(b-d)*MLAT);}
let max=0,nonzero=0,total=0;
for(const f of buildings){const[lo,la]=cent(f);let n=0;for(const p of noise)if(dist(lo,la,p.lon,p.lat)<=R)n++;if(n>0)nonzero++;total+=n;if(n>max)max=n;}
console.log(`join → buildings:${buildings.length} max:${max} withComplaints:${nonzero} avg:${(total/buildings.length).toFixed(2)}`);
EOF
