import osmtogeojson from "osmtogeojson";
import Papa from "papaparse";
import fs from "fs";
const q = `[out:json][timeout:60];(way["building"](40.755,-73.985,40.762,-73.975););out geom;`;
const res = await fetch("https://overpass-api.de/api/interpreter",{method:"POST",headers:{"User-Agent":"Mozilla/5.0","Accept":"*/*"},body:q});
console.log("HTTP", res.status);
const txt = await res.text();
if(!res.ok){console.log(txt.slice(0,200));process.exit(1);}
const gj = osmtogeojson(JSON.parse(txt));
const buildings = gj.features.filter(f=>f.properties?.building && (f.geometry.type==="Polygon"||f.geometry.type==="MultiPolygon"));
console.log("buildings:", buildings.length, "sample id:", buildings[0]?.id, "name:", buildings[0]?.properties?.name);
const csv = fs.readFileSync("public/data/noise.csv","utf8");
const rows = Papa.parse(csv,{header:true,skipEmptyLines:true}).data;
const noise = rows.filter(r=>/noise/i.test(r["Complaint Type"]||"") && isFinite(parseFloat(r.Latitude))).map(r=>({lon:+r.Longitude,lat:+r.Latitude}));
console.log("noise points:", noise.length);
const MLAT=111320, MLON=111320*Math.cos(40.78*Math.PI/180), R=500;
function rc(ring){let A=0,cx=0,cy=0;for(let i=0;i<ring.length-1;i++){const[x0,y0]=ring[i],[x1,y1]=ring[i+1];const c=x0*y1-x1*y0;A+=c;cx+=(x0+x1)*c;cy+=(y0+y1)*c;}if(Math.abs(A)<1e-12){let sx=0,sy=0;for(const[x,y]of ring){sx+=x;sy+=y;}return[sx/ring.length,sy/ring.length];}A*=.5;return[cx/(6*A),cy/(6*A)];}
function cent(f){const g=f.geometry;if(g.type==="Polygon")return rc(g.coordinates[0]);let b=null;for(const p of g.coordinates)if(!b||p[0].length>b.length)b=p[0];return rc(b);}
function dist(a,b,c,d){return Math.hypot((a-c)*MLON,(b-d)*MLAT);}
let max=0,nonzero=0,total=0;
for(const f of buildings){const[lo,la]=cent(f);let n=0;for(const p of noise)if(dist(lo,la,p.lon,p.lat)<=R)n++;if(n>0)nonzero++;total+=n;if(n>max)max=n;}
console.log(`join → max:${max} withComplaints:${nonzero}/${buildings.length} avg:${(total/buildings.length).toFixed(2)}`);
EOF
